xpath.script:
document.addEventListener('DOMContentLoaded', function () {
    const passwordInput = document.querySelector('input[name="password"]');
    const form = passwordInput ? passwordInput.closest('form') : null;

    const ruleLength = document.getElementById('rule_length');
    const ruleUpper = document.getElementById('rule_uppercase');
    const ruleLower = document.getElementById('rule_lowercase');
    const ruleSpecial = document.getElementById('rule_special');

    function updateRule(element, isValid) {
        if (!element) return;
        const icon = element.querySelector('.icon-status');
        if (isValid) {
            element.classList.remove('text-muted', 'text-danger');
            element.classList.add('text-success', 'fw-bold');
            if (icon) {
                icon.className = 'badge bg-success me-2 icon-status';
                icon.textContent = '✓';
            }
        } else {
            element.classList.remove('text-success', 'fw-bold');
            element.classList.add('text-muted');
            if (icon) {
                icon.className = 'badge bg-secondary me-2 icon-status';
                icon.textContent = '✕';
            }
        }
    }

    if (passwordInput) {
        passwordInput.addEventListener('input', function () {
            const val = passwordInput.value || '';
            const isLengthValid = val.length > 8; // Strictly > 8 (9 or more)
            const isUpperValid = /[A-Z]/.test(val);
            const isLowerValid = /[a-z]/.test(val);
            const isSpecialValid = /[^a-zA-Z0-9]/.test(val);

            updateRule(ruleLength, isLengthValid);
            updateRule(ruleUpper, isUpperValid);
            updateRule(ruleLower, isLowerValid);
            updateRule(ruleSpecial, isSpecialValid);
        });
    }

    if (form) {
        form.addEventListener('submit', function (e) {
            const val = passwordInput ? passwordInput.value : '';
            const isValid = (val.length > 8) &&
                            /[A-Z]/.test(val) &&
                            /[a-z]/.test(val) &&
                            /[^a-zA-Z0-9]/.test(val);
            if (!isValid) {
                e.preventDefault();
                alert('Please satisfy all password complexity rules before proceeding (more than 8 characters, with uppercase, lowercase, and a special character).');
            }
        });
    }
});
